export const catalogById = new Map(equipmentCatalog.map(entry => [entry.id, entry]));

// Source identity is bound to the researched model, never to an editable layout
// item's catalogId alone. Hyphen/space formatting is not a different model.
export function getDimensionInfo(entry,item=entry){
  const normalize=value=>String(value??'').trim().toLowerCase().replace(/[\s-]+/g,'');
  const evidence=entry?.dimensionEvidence||entry?.dimensionReference;
  const targetMatches=!!entry&&normalize(item?.modelNumber)===normalize(entry.modelNumber)&&normalize(item?.manufacturer)===normalize(entry.manufacturer);
  const matches=targetMatches&&!!evidence&&normalize(evidence.modelNumber)===normalize(entry.modelNumber)&&
    normalize(evidence.manufacturer)===normalize(entry.manufacturer)&&
    normalize(item?.modelNumber)===normalize(entry.modelNumber)&&normalize(item?.manufacturer)===normalize(entry.manufacturer);
  const sourced=matches&&!!entry.dimensionsIn&&['manufacturer','secondary','legacy-manufacturer'].includes(evidence.quality)&&
    ['exact-model','catalog-model-unrechecked'].includes(evidence.match);
  const kind=evidence&&!targetMatches?'model-mismatch':sourced?evidence.quality:entry?.dimensionReference?'reference-only':evidence&&!matches?'model-mismatch':'unknown';
  const labels={'manufacturer':'Manufacturer · exact model code','secondary':'Secondary source · exact model code',
    'legacy-manufacturer':'Prior manufacturer source · not rechecked','reference-only':evidence?.match==='component-only'?'Component reference only':'Comparable model · estimate only',
    'model-mismatch':'Source model differs from selected model','unknown':'Dimensions unknown'};
  const reviewRequired=!!evidence?.reviewRequired||kind==='legacy-manufacturer'||entry?.modelStatus!=='verified';
  const dimensions=sourced?entry.dimensionsIn:null;
  const convertedCm=dimensions?Object.fromEntries(['length','width','height'].flatMap(key=>dimensions[key]===undefined?[]:[[key,Number((dimensions[key]*2.54).toFixed(4))]])):null;
  return {kind,label:labels[kind],sourced,dimensions,evidence,convertedCm,reviewRequired,
    // Conflicting generations/units must be resolved by an operator. References
    // and component dimensions never populate an equipment footprint.
    canPrefill:sourced&&!evidence.reviewRequired};
}

export function dimensionDescription(entry,item=entry){
  const info=getDimensionInfo(entry,item),e=info.evidence;
  if(!e||info.kind==='model-mismatch')return info.label+'. Enter or retain the actual footprint.';
  const original=e.original,axes=original.height===undefined?'L × W':'L × W × H';
  const values=[original.length,original.width,...(original.height===undefined?[]:[original.height])].join(' × ');
  return info.label+': '+values+' '+e.originalUnits+' ('+axes+'). '+
    (info.sourced&&info.dimensions.height===undefined&&!e.heightRangeIn?'Height unknown; ':'')+
    (e.heightRangeIn?'Adjustable height '+e.heightRangeIn.join('–')+' in. ':'')+
    (info.reviewRequired?'Confirm model/generation and measure on site. ':'')+
    (e.conflicts?.length?'Conflicting specifications; enter actual dimensions. ':'')+
    (e.configurationNote?e.configurationNote+' ':'')+e.reference+'. Reviewed '+e.reviewedAt+'. '+
    (e.accessNote?e.accessNote+' ':'')+'Source dimensions are not an on-site measurement or exercise clearance.';
}

export function getDimensionCoverage(entries=equipmentCatalog){
  const count=predicate=>({groups:entries.filter(predicate).length,units:entries.filter(predicate).reduce((sum,e)=>sum+e.quantity,0)});
  return {total:count(()=>true),sourced:count(e=>getDimensionInfo(e).sourced),
    manufacturer:count(e=>getDimensionInfo(e).kind==='manufacturer'),secondary:count(e=>getDimensionInfo(e).kind==='secondary'),
    legacy:count(e=>getDimensionInfo(e).kind==='legacy-manufacturer'),reference:count(e=>getDimensionInfo(e).kind==='reference-only'),
    unknown:count(e=>getDimensionInfo(e).kind==='unknown'),missing:count(e=>!getDimensionInfo(e).sourced),
    conflicts:count(e=>!!e.dimensionEvidence?.conflicts?.length)};
}

export function getCatalogRecord(id) {
  return catalogById.get(id) || null;
}

export function getAvailableInventoryIds(entry, placedItems = []) {
  if (!entry) return [];
  const assigned = new Set(placedItems.map(i => i.inventoryId).filter(Boolean));
  return entry.inventoryIds.filter(id => !assigned.has(id));
}

export function findCatalogRecords({query='',sourcedOnly=false,availableOnly=false}={},placedItems=[]){
  const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  return equipmentCatalog.filter(entry=>{
    if(sourcedOnly&&!getDimensionInfo(entry).sourced)return false;
    if(availableOnly&&!getAvailableInventoryIds(entry,placedItems).length)return false;
    const text=[entry.id,entry.area,entry.name,entry.manufacturer,entry.modelNumber,
      ...entry.inventoryIds,...entry.muscleGroups,...entry.exercises,...entry.capabilities].join(' ').toLowerCase();
    return terms.every(term=>text.includes(term));
  });
}

export function applyCatalogIdentity(item, entry, inventoryId = '') {
  if (!entry || !item || !['strength', 'free', 'cardio'].includes(item.category)) {
    throw new Error('Choose an equipment footprint and a valid catalog entry.');
  }
  if (inventoryId && !entry.inventoryIds.includes(inventoryId)) {
    throw new Error('The inventory ID does not belong to this model.');
  }
  return {
    ...item,
    name: entry.name,
    catalogId: entry.id,
    inventoryId,
    manufacturer: entry.manufacturer,
    modelNumber: entry.modelNumber || '',
    modelStatus: entry.modelStatus,
    muscleGroups: item.catalogId===entry.id&&Array.isArray(item.muscleGroups)?[...item.muscleGroups]:[...entry.muscleGroups],
    exercises: item.catalogId===entry.id&&Array.isArray(item.exercises)?[...item.exercises]:[...entry.exercises],
    capabilities: item.catalogId===entry.id&&Array.isArray(item.capabilities)?[...item.capabilities]:[...entry.capabilities],
    // Dimensions and coordinates remain untouched when linking an existing item.
  };
}
